{"path": "durations.py", "content": "import re

_UNITS = {'h': 3600, 'm': 60, 's': 1}
_ORDER = 'hms'
_FULL = re.compile(r'[0-9]+[hms](?: *[0-9]+[hms])*')
_PART = re.compile(r'([0-9]+)([hms])')


def parse_duration(text):
    """See SPEC.md."""
    if not isinstance(text, str) or not _FULL.fullmatch(text):
        raise ValueError(f'invalid duration: {text!r}')
    total = 0
    last = -1
    for number, unit in _PART.findall(text):
        index = _ORDER.index(unit)
        if index <= last:
            raise ValueError(f'repeated or out-of-order unit in {text!r}')
        last = index
        total += int(number) * _UNITS[unit]
    return total
"}

